import{_ as o,o as l,c as r,a3 as i,j as e,t as s,a as n}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"安裝 ComfyUI","description":"安裝 ComfyUI，開啟局域網監聽，供 MiniTavern 生圖連接使用默認 workflow。","frontmatter":{"title":"安裝 ComfyUI","description":"安裝 ComfyUI，開啟局域網監聽，供 MiniTavern 生圖連接使用默認 workflow。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"安裝 ComfyUI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"安裝 ComfyUI，開啟局域網監聽，供 MiniTavern 生圖連接使用默認 workflow。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen/comfyui"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen/comfyui"}]]},"headers":[],"relativePath":"zh-TW/local/image-gen/comfyui.md","filePath":"zh-TW/local/image-gen/comfyui.md","lastUpdated":1791599898000}'),p={name:"zh-TW/local/image-gen/comfyui.md"};function d(t,a,h,c,g,k){return l(),r("div",null,[a[2]||(a[2]=i(`<h1 id="安裝-comfyui" tabindex="-1">安裝 ComfyUI <a class="header-anchor" href="#安裝-comfyui" aria-label="Permalink to &quot;安裝 ComfyUI&quot;">​</a></h1><p>ComfyUI 是節點式本地生圖前端，對新模型支持較快。<br> MiniTavern 通過 ComfyUI 的 HTTP API（<code>/prompt</code> 等）提交<strong>內置默認工作流</strong>；你無需在 App 裡手寫節點圖即可出圖。</p><p>官方文檔：<a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">docs.comfy.org</a> · 倉庫：<a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">Comfy-Org/ComfyUI</a></p><h2 id="硬件建議" tabindex="-1">硬件建議 <a class="header-anchor" href="#硬件建議" aria-label="Permalink to &quot;硬件建議&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顯存</th><th>建議</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5 等較小工作流</td></tr><tr><td>8–12GB</td><td>SDXL、部分快速 Flux 變體更現實</td></tr><tr><td>Apple Silicon</td><td>可原生跑，一般慢於同級 NVIDIA</td></tr></tbody></table><h2 id="方式-a-windows-便攜包-推薦" tabindex="-1">方式 A：Windows 便攜包（推薦） <a class="header-anchor" href="#方式-a-windows-便攜包-推薦" aria-label="Permalink to &quot;方式 A：Windows 便攜包（推薦）&quot;">​</a></h2><ol><li>打開 <a href="https://www.comfy.org/download" target="_blank" rel="noreferrer">ComfyUI 發佈頁 / 官網下載</a>（或社區提供的 <code>ComfyUI_windows_portable</code> 包）。</li><li>解壓到非系統盤路徑（路徑儘量短、無中文空格亦可）。</li><li>有 NVIDIA 時運行 <code>run_nvidia_gpu.bat</code>；僅 CPU 時用對應 CPU 腳本。</li><li>本機瀏覽器打開提示的地址，常見為：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><h2 id="方式-b-desktop-應用" tabindex="-1">方式 B：Desktop 應用 <a class="header-anchor" href="#方式-b-desktop-應用" aria-label="Permalink to &quot;方式 B：Desktop 應用&quot;">​</a></h2><ol><li>安裝 <a href="https://docs.comfy.org/" target="_blank" rel="noreferrer">ComfyUI Desktop</a>。</li><li>設置 → Server Configuration（或同類「服務器 / 網絡」項）： <ul><li><strong>Listen Address</strong> 改為 <code>0.0.0.0</code>（默認 <code>127.0.0.1</code> 時手機連不上）</li><li>記下 <strong>Port</strong>（Desktop 常見 <strong>8000</strong>，與便攜版 8188 不同）</li></ul></li><li>重啟後再用局域網 IP 訪問。</li></ol><h2 id="方式-c-手動-git-macos-linux-進階" tabindex="-1">方式 C：手動 Git（macOS / Linux / 進階） <a class="header-anchor" href="#方式-c-手動-git-macos-linux-進階" aria-label="Permalink to &quot;方式 C：手動 Git（macOS / Linux / 進階）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Comfy-Org/ComfyUI.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ComfyUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows: venv\\Scripts\\activate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 按顯卡安裝匹配的 PyTorch（見 PyTorch 官網）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span></span></code></pre></div><h2 id="開啟局域網-連手機必做" tabindex="-1">開啟局域網（連手機必做） <a class="header-anchor" href="#開啟局域網-連手機必做" aria-label="Permalink to &quot;開啟局域網（連手機必做）&quot;">​</a></h2><h3 id="便攜包-命令行" tabindex="-1">便攜包 / 命令行 <a class="header-anchor" href="#便攜包-命令行" aria-label="Permalink to &quot;便攜包 / 命令行&quot;">​</a></h3><p>編輯啟動腳本（如 <code>run_nvidia_gpu.bat</code>），在 <code>main.py</code> 後增加：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--listen</span></span></code></pre></div><p>完整示例：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\python_embeded\\python.exe -s ComfyUI\\main.py --windows-standalone-build --listen</span></span></code></pre></div><table tabindex="0"><thead><tr><th>參數</th><th>作用</th></tr></thead><tbody><tr><td><code>--listen</code></td><td>無參數時監聽所有網卡，允許局域網訪問</td></tr><tr><td><code>--port 8188</code></td><td>可選改端口</td></tr><tr><td><code>--enable-cors-header</code></td><td>瀏覽器跨域需要時再加；手機 App 直連 API 通常不必</td></tr></tbody></table><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>見上文：Listen 設為 <code>0.0.0.0</code>，端口以界面為準。</p><h2 id="放置模型" tabindex="-1">放置模型 <a class="header-anchor" href="#放置模型" aria-label="Permalink to &quot;放置模型&quot;">​</a></h2><p>將 checkpoint（<code>.safetensors</code>）放入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComfyUI/models/checkpoints/</span></span></code></pre></div><p>在界面中按 <code>R</code> 刷新模型列表，或重啟。先確保能在 ComfyUI 網頁裡手動跑通默認文生圖，再連 App。</p><p>模型來源示例：<a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> · <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a>。</p><h2 id="驗證" tabindex="-1">驗證 <a class="header-anchor" href="#驗證" aria-label="Permalink to &quot;驗證&quot;">​</a></h2><p>本機：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8188</span></span></code></pre></div><p>局域網（換成電腦 IP；Desktop 注意端口）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:8188</span></span></code></pre></div><p>手機瀏覽器能打開同一地址，說明網絡與監聽正常。</p><h2 id="與-minitavern-的差異-請先讀" tabindex="-1">與 MiniTavern 的差異（請先讀） <a class="header-anchor" href="#與-minitavern-的差異-請先讀" aria-label="Permalink to &quot;與 MiniTavern 的差異（請先讀）&quot;">​</a></h2><ul><li>App 使用<strong>內置默認 workflow</strong>，一般會選用你機器上可用的 checkpoint。</li><li>電腦休眠、合蓋後服務會停；IP 變更後需在 App 裡改 Base URL。</li></ul><h2 id="多張參考圖" tabindex="-1">多張參考圖 <a class="header-anchor" href="#多張參考圖" aria-label="Permalink to &quot;多張參考圖&quot;">​</a></h2><p>角色、用戶身份和聊天附圖會作為多張參考圖發給 ComfyUI。默認安裝即可使用，不必先裝 IPAdapter。</p><p>App 會做兩件事：</p><ol><li>把每一張參考圖上傳到 ComfyUI（<code>/upload/image</code>）。</li><li>若你沒有改 workflow，就把內置文生圖改成圖生圖：每張圖一個 LoadImage，縮放到本次寬高後橫向拼在一起，再編碼進採樣器。採樣強度大約 0.55。</li></ol><p>只要 ComfyUI 能跑通默認文生圖，多張參考圖就會走上面這條路徑。</p><h3 id="自己接-loadimage-或-ipadapter" tabindex="-1">自己接 LoadImage 或 IPAdapter <a class="header-anchor" href="#自己接-loadimage-或-ipadapter" aria-label="Permalink to &quot;自己接 LoadImage 或 IPAdapter&quot;">​</a></h3><p>若要鎖臉更穩，或已經有自己的節點圖，在 <strong>LoadImage</strong> 節點的 <code>image</code> 輸入裡寫成帶引號的佔位符，從 0 起，一張圖一個：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;{{reference_image_0}}&quot;</span></span>
<span class="line"><span>&quot;{{reference_image_1}}&quot;</span></span></code></pre></div>`,42)),e("p",null,[e("code",null,'"'+s(t.reference_image)+'"',1),a[0]||(a[0]=n(" 和 ",-1)),e("code",null,'"'+s(t.init_image)+'"',1),a[1]||(a[1]=n(" 都表示第一張。",-1))]),a[3]||(a[3]=i('<p>把這份 API 格式的 workflow JSON 填進生圖連接的 workflow 後，App 只把佔位符換成已上傳的檔名，不再改你的節點。</p><p>建議：</p><ol><li>在 ComfyUI 網頁裡搭好圖（例如 LoadImage → IPAdapter → KSampler → SaveImage），確認能手動出圖。</li><li>打開 <strong>Save (API Format)</strong>，把 JSON 裡對應 LoadImage 的 <code>image</code> 改成上面的佔位符。</li><li>在 MiniTavern <strong>設定 → 生圖 → 生圖連接</strong> 裡貼上這段 JSON 並保存。</li><li>測連或在聊天裡生一張帶參考圖的圖，確認 Comfy 隊列裡能看到上傳的圖片。</li></ol><p>自訂 JSON 裡既沒有採樣器（KSampler），也沒有上述佔位符時，參考圖寫不進去，App 會提示按本節修改。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./connect-app">在 MiniTavern 中配置</a></li><li>總覽：<a href="./index">生圖模型部署</a></li></ul>',6))])}const b=o(p,[["render",d]]);export{u as __pageData,b as default};
